protected boolean checkIfExtendedDimensionsAreMatched(
    Common _journalTransaction,
    TAMRebateQueryBuilder _rebateQueryBuilder,
    TAMRebateDate _rebateDate,
    TAMRebateTable _rebateTable)
{

    boolean ret = next checkIfExtendedDimensionsAreMatched(
        _journalTransaction,
        _rebateQueryBuilder,
        _rebateDate,
        _rebateTable);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        ret = this.checkAttributesMatchedWithPriority(_journalTransaction, _rebateQueryBuilder, _rebateDate, _rebateTable)
            && GUPRebateMatchingHelper::checkIfRecordLinkedWithPriceTree(_journalTransaction, _rebateQueryBuilder, rebateTable);
    }

    return ret;
}

protected boolean checkAttributesMatchedWithPriority(
    Common _journalTransaction,
    TAMRebateQueryBuilder _rebateQueryBuilder,
    TAMRebateDate _rebateDate,
    TAMRebateTable _rebateTable)
{

    boolean ret = true;

    if (_rebateTable.ModuleInventCustVend == ModuleInventCustVend::Cust)
    {
        ret = GUPRebateMatchingHelper::checkIfPricingAttributesAreMatched (
                _journalTransaction,
                rebateQueryBuilder,
                _rebateDate,
                _rebateTable);
    }

    return ret;
}
